const toIng = (x: I | [string, number, Unit, string | undefined, true]): RecipeIngredient => ({
  id: x[0], qty: x[1], unit: x[2], note: x[3], optional: (x as unknown[])[4] === true ? true : undefined,
});
const r = (x: R): Recipe => ({ ...x, ingredients: x.ingredients.map(toIng) });

